import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.Random;

/**
 * Centralizes instantiation rules for all concrete organism types.
 */
public class OrganismFactory
{
    private static final List<Class<? extends Organism>> CREATION_ORDER = List.of(
            Grass.class,
            Deer.class,
            Coyote.class,
            Wolf.class,
            Eagle.class,
            Mouse.class,
            Hunter.class
    );

    private final SimulationConfig config;
    private final RandomProvider randomProvider;
    private final DiseaseService diseaseService;
    private final Map<Class<? extends Organism>, OrganismCreator<? extends Organism>> creators;

    public OrganismFactory(RandomProvider randomProvider, SimulationConfig config, DiseaseService diseaseService)
    {
        this.randomProvider = randomProvider;
        this.config = config;
        this.diseaseService = diseaseService;
        this.creators = Map.ofEntries(
                Map.entry(Grass.class, (field, location, options) -> new Grass(field, location)),
                Map.entry(Hunter.class, (field, location, options) -> new Hunter(field, location)),
                Map.entry(Deer.class, (field, location, options) -> new Deer(options.randomAge(), field, location, requireSex(options))),
                Map.entry(Coyote.class, (field, location, options) -> new Coyote(options.randomAge(), field, location, requireSex(options))),
                Map.entry(Wolf.class, (field, location, options) -> new Wolf(options.randomAge(), field, location, requireSex(options))),
                Map.entry(Eagle.class, (field, location, options) -> new Eagle(options.randomAge(), field, location, requireSex(options))),
                Map.entry(Mouse.class, (field, location, options) -> new Mouse(options.randomAge(), field, location, requireSex(options)))
        );
    }

    public List<Actor> populate(Field field)
    {
        List<Actor> actors = new ArrayList<>();
        int hunterCount = 0;

        field.clear();
        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                Location location = new Location(row, col);
                Organism organism = maybeCreateOrganism(field, location, hunterCount);
                if(organism != null) {
                    actors.add((Actor) organism);
                    if(organism instanceof Hunter) {
                        hunterCount++;
                    }
                }
            }
        }

        return actors;
    }

    public List<Actor> createGrassPatches(Field field, Environment environment)
    {
        Random rand = randomProvider.getRandom();
        if(!environment.getWeatherService().canCreateGrassPatches()) {
            return List.of();
        }

        double creationRate = config.getCreationProbability(Grass.class);
        List<Actor> grassActors = new ArrayList<>();
        for(Location location : field.getMovementService().getRandomFreePatches(field, creationRate)) {
            if(rand.nextDouble() <= creationRate) {
                grassActors.add(createOffspring(Grass.class, field, location));
            }
        }

        return grassActors;
    }

    public <T extends Organism> T createInitialOrganism(Class<T> organismClass, Field field, Location location)
    {
        Animal.Gender sex = getRandomSex();
        return create(organismClass, field, location, new OrganismCreationOptions(true, sex));
    }

    public <T extends Organism> T createOffspring(Class<T> organismClass, Field field, Location location)
    {
        return create(organismClass, field, location, new OrganismCreationOptions(false, null));
    }

    public <T extends Organism> T createOffspring(Class<T> organismClass,
            Field field,
            Location location,
            Animal.Gender sex)
    {
        return create(organismClass, field, location, new OrganismCreationOptions(false, sex));
    }

    private Organism maybeCreateOrganism(Field field, Location location, int hunterCount)
    {
        Random rand = randomProvider.getRandom();
        for(Class<? extends Organism> organismClass : CREATION_ORDER) {
            if(organismClass == Hunter.class && hunterCount >= config.getHunterLimit()) {
                continue;
            }

            if(rand.nextDouble() <= config.getCreationProbability(organismClass)) {
                return createInitialOrganism(organismClass, field, location);
            }
        }

        return null;
    }

    private <T extends Organism> T create(Class<T> organismClass,
            Field field,
            Location location,
            OrganismCreationOptions options)
    {
        OrganismCreator<? extends Organism> creator = creators.get(organismClass);
        if(creator == null) {
            throw new IllegalArgumentException("Unsupported organism type: " + organismClass.getName());
        }

        T organism = organismClass.cast(creator.create(field, location, options));
        diseaseService.initializeOrganism(organism);
        return organism;
    }

    private Animal.Gender getRandomSex()
    {
        return randomProvider.getRandom().nextBoolean()
                ? Animal.Gender.MALE
                : Animal.Gender.FEMALE;
    }

    private static Animal.Gender requireSex(OrganismCreationOptions options)
    {
        if(options.sex() == null) {
            throw new IllegalArgumentException("Animal creation requires a sex.");
        }
        return options.sex();
    }

    private record OrganismCreationOptions(boolean randomAge, Animal.Gender sex) { }

    @FunctionalInterface
    private interface OrganismCreator<T extends Organism>
    {
        T create(Field field, Location location, OrganismCreationOptions options);
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Random;
import java.util.Set;

/**
 * A class representing shared characteristics of animals.
 *
 * @version 2022.03.02
 */
public abstract class Animal extends Organism implements Actor
{
    protected int age;
    protected boolean isNocturnal;
    protected int foodLevel;
    protected Gender sex;

    // An animal is either male or female 
    protected enum Gender {
        MALE,
        FEMALE
    }


    // Declaring abstract methods to obtain fields used by subclasses
    // These methods have been declared in order to use common methods in the Animal class, reducing repeatability
    protected abstract int getBreedingAge();
    protected abstract int getMaxLitterSize();
    protected abstract double getBreedingProbability();
    protected abstract int getMaxAge();
    protected abstract int getMaxFoodLevel();
    protected abstract Set<Class<? extends Organism>> getDiet();


    /**
     * Create a new animal at location in field.
     *
     * @param field The field currently occupied.
     * @param location The location within the field.
     * @param randomAge The animal's random starting age.
     * @param sex The animal's gender. 
     */
    public Animal(RandomProvider randomProvider, Field field, Location location, boolean randomAge, Gender sex)
    {
        super(randomProvider, field, location);
        this.sex = sex;
        Random rand = getRandomProvider().getRandom();
        if(randomAge) {
            this.age = rand.nextInt(getMaxAge());
            foodLevel = rand.nextInt(getMaxFoodLevel());
        }
        else {
            this.age = 0;
            foodLevel = getMaxFoodLevel();
        }
    }

    /**
     * Make this animal act - that is: make it do
     * whatever it wants/needs to do.
     * @param newAnimals A list to receive newly born animals.
     * @param environment The environment that the animal resides in.
     */
    public void act(List<Actor> newAnimals, Environment environment)
    {
        incrementAge();
        incrementHunger();
        if(isAlive()) {
            giveBirth(newAnimals, environment);
            move(environment);
        }
    }

    /**
     * Look for food adjacent to the current location.
     * Only the first food is eaten.
     * @return Where food was found, or null if it wasn't.
     */
    protected MovementService.MovementDecision findFood(Environment environment)
    {
        Field field = getField();
        MovementService movementService = field.getMovementService();
        DiseaseService diseaseService = field.getDiseaseService();
        List<Location> adjacent = movementService.getAdjacentLocations(field, getLocation());
        diseaseService.applyAdjacentExposure(this, adjacent, field);
        return movementService.resolveAnimalMovement(this, environment, adjacent);
    }

    /**
     * Check whether this animal is to give birth at this step.
     * New births will be made into free adjacent locations.
     * @param newAnimals A list to return newly born animals.
     * @param environment The environment that the animal resides in. 
     */
    protected void giveBirth(List<Actor> newAnimals, Environment environment)
    {
        Field field = getField();
        List<Location> free = field.getMovementService().getFreeAdjacentLocations(field, getLocation());
        int births = breed();
        for(int b = 0; b < births && !free.isEmpty(); b++) {
            Location loc = free.remove(0);
            Gender sex = getRandomProvider().getRandom().nextBoolean() ? Gender.MALE : Gender.FEMALE;
            newAnimals.add(createYoung(field, loc, sex));
        }
    }

    protected Animal createYoung(Field field, Location location, Gender sex)
    {
        return field.getOrganismFactory().createOffspring(getClass().asSubclass(Animal.class), field, location, sex);
    }

    /**
     * Returns true if the animal is awake or not.
     */
    public boolean isAwake(Environment environment)
    {
        if(isNocturnal){
            return !environment.getTime().isDay();
        }
        return environment.getTime().isDay();
    }

    /**
     * Generates a number representing the number of births,
     * if it can breed.
     * @return The number of births (may be zero)
     */
    protected int breed()
    {
        Random rand = getRandomProvider().getRandom();
        int births = 0;
        if(canBreed() && rand.nextDouble() <= getBreedingProbability()) {
            births = rand.nextInt(getMaxLitterSize()) + 1;
            Animal mate = (Animal) getPotentialMates().get(rand.nextInt(getPotentialMates().size()));
            getField().getDiseaseService().applySexualExposure(this, mate);
        }
        return births;
    }

    /**
     * Returns true if the animal is able to breed.
     * Returns false if otherwise. 
     */
    protected boolean canBreed()
    {
        return age >= getBreedingAge() && !getPotentialMates().isEmpty();
    }

    /**
     * Returns a list of potential mates. Mates have to be
     * of a opposite gender. 
     * @return List<Organism> A list of potential mates.
     */
    protected List<Organism> getPotentialMates()
    {
        if(getField() != null){
            return getField().getMovementService().findPotentialMates(this);
        }
        return new ArrayList<>();
    }


    /**
     * Increase the age. This could result in the animal's death.
     */
    protected void incrementAge()
    {
        this.age++;
        if(this.age > getMaxAge()) {
            setDead();
        }
    }

    /**
     * Make this animal more hungry. This could result in the animal's death.
     */
    protected void incrementHunger()
    {
        foodLevel--;
        if(foodLevel <= 0) {
            setDead();
        }
    }

    private void move(Environment environment)
    {
        MovementService.MovementDecision movementDecision = findFood(environment);
        if(movementDecision.consumedOrganism() != null) {
            consume(movementDecision.consumedOrganism());
        }

        if(movementDecision.targetLocation() != null) {
            getField().getMovementService().moveOrganism(this, movementDecision.targetLocation());
        }
        else if(movementDecision.overcrowded()) {
            setDead();
        }
    }

    private void consume(Organism food)
    {
        getField().getDiseaseService().applyFoodborneExposure(this, food);
        if(food.isAlive()) {
            food.setDead();
            int newFoodLevel = foodLevel + food.getFoodValue();
            foodLevel = Math.min(newFoodLevel, getMaxFoodLevel());
        }
    }

}

import java.util.*;

/**
 * A simple model of a hunter. 
 * Hunters hunt all of the species in the simulation.
 * @version 2022.03.02
 */
public class Hunter extends Organism implements Actor
{
    // A hunter hunts every species. 
    private static final Set<Class<? extends Organism>> DIET = new HashSet<>(Arrays.asList(
            Deer.class,
            Mouse.class,
            Wolf.class,
            Coyote.class,
            Eagle.class
    ));


    /**
     * Creates a new hunter.
     * @param field The field currently occupied.
     * @param location  The location within the field.
     */
    public Hunter(Field field, Location location)
    {
        super(field.getRandomProvider(), field, location);
    }

    @Override
    protected int getFoodValue()
    {
        return 0;
    }

    /**
     * Makes the hunter hunt for nearby animals. 
     * @param environment The environment that the hunter resides in. 
     * @param newActors A list to receive new actors. 
     */
    public void act(List<Actor> newActors, Environment environment)
    {
        if(isAlive()) {
            move();
        }
    }

    /**
     * Returns the species that hunters can target.
     */
    protected Set<Class<? extends Organism>> getDiet()
    {
        return DIET;
    }

    private void move()
    {
        Field field = getField();
        MovementService movementService = field.getMovementService();
        List<Location> adjacentLocations = movementService.getAdjacentLocations(field, getLocation());
        MovementService.MovementDecision movementDecision = movementService.resolveHunterMovement(this, adjacentLocations);

        if(movementDecision.consumedOrganism() != null) {
            movementDecision.consumedOrganism().setDead();
        }

        if(movementDecision.targetLocation() != null) {
            movementService.moveOrganism(this, movementDecision.targetLocation());
        }
    }
}

import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;

/**
 * Immutable snapshot of the current simulation state.
 */
public class SimulationState
{
    private final int step;
    private final WeatherType weather;
    private final String time;
    private final Field field;
    private final Map<Class<?>, Integer> populationCounts;
    private final int diseasedPopulation;
    private final boolean viable;

    private SimulationState(int step,
            WeatherType weather,
            String time,
            Field field,
            Map<Class<?>, Integer> populationCounts,
            int diseasedPopulation,
            boolean viable)
    {
        this.step = step;
        this.weather = weather;
        this.time = time;
        this.field = field;
        this.populationCounts = Collections.unmodifiableMap(populationCounts);
        this.diseasedPopulation = diseasedPopulation;
        this.viable = viable;
    }

    public static SimulationState capture(int step, Environment environment, Field field)
    {
        DiseaseService diseaseService = field.getDiseaseService();
        Map<Class<?>, Integer> populationCounts = new LinkedHashMap<>();
        for(Class<?> actorClass : SimulationInfo.ALL_ACTORS) {
            populationCounts.put(actorClass, 0);
        }

        int diseasedPopulation = 0;
        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                Object actor = field.getObjectAt(row, col);
                if(actor != null) {
                    populationCounts.merge(actor.getClass(), 1, Integer::sum);
                    if(actor instanceof Organism organism && diseaseService.isDiseased(organism)) {
                        diseasedPopulation++;
                    }
                }
            }
        }

        int livingSpecies = 0;
        for(int count : populationCounts.values()) {
            if(count > 0) {
                livingSpecies++;
            }
        }

        return new SimulationState(
                step,
                environment.getWeather().getCurrentWeather(),
                environment.getTime().getCurrentTimeString(),
                field,
                populationCounts,
                diseasedPopulation,
                livingSpecies > 2
        );
    }

    public int getStep()
    {
        return step;
    }

    public WeatherType getWeather()
    {
        return weather;
    }

    public String getTime()
    {
        return time;
    }

    public Field getField()
    {
        return field;
    }

    public int getPopulationCount(Class<?> actorClass)
    {
        return populationCounts.getOrDefault(actorClass, 0);
    }

    public Map<Class<?>, Integer> getPopulationCounts()
    {
        return populationCounts;
    }

    public int getDiseasedPopulation()
    {
        return diseasedPopulation;
    }

    public boolean isViable()
    {
        return viable;
    }
}

import java.util.IdentityHashMap;
import java.util.List;
import java.util.Map;
import java.util.Random;

/**
 * Centralizes disease creation, infection state, and transmission rules.
 */
public class DiseaseService
{
    private static final double RANDOM_CONTRACTION_RATE = 0.002;

    private final RandomProvider randomProvider;
    private final Map<Organism, Disease> infections;

    public DiseaseService(RandomProvider randomProvider)
    {
        this.randomProvider = randomProvider;
        this.infections = new IdentityHashMap<>();
    }

    public void initializeOrganism(Organism organism)
    {
        if(organism instanceof Animal) {
            maybeInfectAtCreation(organism);
        }
    }

    public void reset()
    {
        infections.clear();
    }

    public void unregister(Organism organism)
    {
        infections.remove(organism);
    }

    public boolean isDiseased(Organism organism)
    {
        return infections.containsKey(organism);
    }

    public Disease getDisease(Organism organism)
    {
        return infections.get(organism);
    }

    public void infect(Organism organism, Disease disease)
    {
        infections.put(organism, disease);
    }

    public boolean processPreAct(Animal animal)
    {
        if(!animal.isAlive()) {
            return false;
        }

        if(shouldKillByPropagation(animal)) {
            kill(animal);
            return false;
        }

        maybeInfectAtCreation(animal);
        return animal.isAlive();
    }

    public void processPostAct(Animal animal)
    {
        if(animal.isAlive() && shouldKillByLethality(animal)) {
            kill(animal);
        }
    }

    public void applyAdjacentExposure(Animal animal, List<Location> adjacentLocations, Field field)
    {
        for(Location location : adjacentLocations) {
            Object nearby = field.getObjectAt(location);
            if(nearby instanceof Organism organism
                    && !(nearby instanceof Hunter)
                    && isDiseased(organism)
                    && getDisease(organism).getDiseaseType() != DiseaseType.CONTACT
                    && succeeds(getDisease(organism).getPropagationRate())) {
                infect(animal, getDisease(organism));
                break;
            }
        }
    }

    public void applyFoodborneExposure(Animal animal, Organism food)
    {
        if(isDiseased(food)
                && getDisease(food).getDiseaseType() == DiseaseType.FOODBORNE
                && succeeds(getDisease(food).getPropagationRate())) {
            infect(animal, getDisease(food));
        }
    }

    public void applySexualExposure(Animal animal, Animal mate)
    {
        if(isDiseased(mate) && getDisease(mate).getDiseaseType() == DiseaseType.SEXUAL) {
            infect(animal, getDisease(mate));
        }
    }

    public Disease createRandomDisease()
    {
        return new Disease(randomProvider);
    }

    private void maybeInfectAtCreation(Organism organism)
    {
        if(!isDiseased(organism) && succeeds(RANDOM_CONTRACTION_RATE)) {
            infect(organism, createRandomDisease());
        }
    }

    private boolean shouldKillByPropagation(Animal animal)
    {
        return isDiseased(animal) && succeeds(getDisease(animal).getPropagationRate());
    }

    private boolean shouldKillByLethality(Animal animal)
    {
        return isDiseased(animal) && succeeds(getDisease(animal).getLethalityRate());
    }

    private boolean succeeds(double threshold)
    {
        Random rand = randomProvider.getRandom();
        return threshold <= rand.nextDouble();
    }

    private void kill(Organism organism)
    {
        organism.setDead();
        unregister(organism);
    }
}

