import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;

/**
 * Centralizes actor lifecycle management and per-step update sequencing.
 */
public class ActorService
{
    private final List<Actor> actors;
    private final Field field;
    private final OrganismFactory organismFactory;
    private final DiseaseService diseaseService;

    public ActorService(Field field, OrganismFactory organismFactory, DiseaseService diseaseService)
    {
        this.actors = new ArrayList<>();
        this.field = field;
        this.organismFactory = organismFactory;
        this.diseaseService = diseaseService;
    }

    public void reset()
    {
        actors.clear();
        actors.addAll(organismFactory.populate(field));
    }

    public void updateActors(Environment environment, int step)
    {
        List<Actor> newActors = new ArrayList<>();
        for(Iterator<Actor> iterator = actors.iterator(); iterator.hasNext(); ) {
            Actor actor = iterator.next();
            updateActor(actor, newActors, environment);
            maybeGrowPlant(actor, step);
            removeIfDead(actor, iterator);
        }

        actors.addAll(newActors);
        actors.addAll(organismFactory.createGrassPatches(field, environment));
    }

    private void updateActor(Actor actor, List<Actor> newActors, Environment environment)
    {
        if(actor instanceof Animal animal) {
            if(!animal.isAwake(environment)) {
                return;
            }
            if(!diseaseService.processPreAct(animal)) {
                return;
            }
        }

        if(actor.isAlive()) {
            actor.act(newActors, environment);
            if(actor instanceof Animal animal) {
                diseaseService.processPostAct(animal);
            }
        }
    }

    private void maybeGrowPlant(Actor actor, int step)
    {
        if(actor instanceof Plant plant && step % plant.getStepsPerStage() == 0) {
            plant.incrementGrowth();
        }
    }

    private void removeIfDead(Actor actor, Iterator<Actor> iterator)
    {
        if(!actor.isAlive()) {
            if(actor instanceof Organism organism) {
                diseaseService.unregister(organism);
            }
            iterator.remove();
        }
    }
}

import java.util.List;

/**
 * A simple predator-prey simulator, based on a rectangular field
 * containing different organisms.
 *
 * @version 2022.03.02
 */
public class Simulator
{
    private boolean playingSimulation;
    private int remainingSteps;

    // The current state of the field.
    private final Field field;
    // The current step of the simulation.
    private int step;
    // Environment in the simulation.
    private final Environment environment;
    // Configuration and actor creation rules for the simulation.
    private final SimulationConfig config;
    private final RandomProvider randomProvider;
    private final DiseaseService diseaseService;
    private final WeatherService weatherService;
    private final MovementService movementService;
    private final OrganismFactory organismFactory;
    private final ActorService actorService;
    // Published state for observers.
    private final List<SimulationObserver> observers;
    private SimulationState currentState;

    /**
     * A simulator constructor to set the creation probability of each actor.
     * This constructor can be used to test different combinations of probabilities.
     */
    public Simulator(double grassProbability,
            double deerProbability,
            double coyoteProbability,
            double wolfProbability,
            double eagleProbability,
            double hunterProbability,
            double mouseProbability)
    {
        this(
                new RandomProvider(),
                SimulationConfig.withCreationProbabilities(
                        grassProbability,
                        deerProbability,
                        coyoteProbability,
                        wolfProbability,
                        eagleProbability,
                        hunterProbability,
                        mouseProbability
                ),
                SimulationConfig.DEFAULT_DEPTH,
                SimulationConfig.DEFAULT_WIDTH
        );
    }

    /**
     * Construct a simulation field with default size.
     */
    public Simulator()
    {
        this(new RandomProvider(), SimulationConfig.defaultConfig(), SimulationConfig.DEFAULT_DEPTH, SimulationConfig.DEFAULT_WIDTH);
    }

    /**
     * Create a simulation field with the given size.
     * @param depth Depth of the field. Must be greater than zero.
     * @param width Width of the field. Must be greater than zero.
     */
    public Simulator(int depth, int width)
    {
        this(new RandomProvider(), SimulationConfig.defaultConfig(), depth, width);
    }

    public Simulator(RandomProvider randomProvider)
    {
